SELECT jsonb_build_object('model','RuntimeCommandReceipt','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,owner_module_id,operation,subject_scope,semantic_key,fingerprint,state,source_revision,result_schema_id,result_schema_version,result_digest,result_body,created_at,mutation_transaction_id FROM platform.runtime_command_receipt WHERE id IN ('7282489a-b97c-5bc4-8a52-dd343c7d4646'::uuid)) observed;
SELECT jsonb_build_object('model','RuntimeOutboxMessage','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,command_receipt_id,kind,producer_owner,aggregate_kind,aggregate_id,source_revision,source_generation,ordinal,name,schema_version,payload_schema_id,payload_hash,payload,correlation_id,causation_id,correction_of_id,occurred_at,effective_at,created_at,mutation_transaction_id FROM platform.runtime_outbox_message WHERE id IN ('422bb5cb-5fad-5bb4-9c0e-1ad67229d5dd'::uuid,'68b8ace5-8aff-5fac-8906-3a10ea333e2c'::uuid)) observed;
